// =====================================================================
//  VAMPIRE WEAKNESS (Monster Manual 2024): Court of Ravenloft world installer, Foundry v13 (Chris's Premades 1). Safe to re-run. (1.7.7)
//  Generated by tools/court-boss-build (vampire-weakness-core.js, one template for v13 and v14): edit there, then rebuild.
//  Run by Nix Fix on the Court vampires (Dracula, Lucian, Valintina, Sydmore, Dayus Manroe and the (Boss) copies),
//  or as a Script macro (GM) with their tokens selected. Gives each one a "Vampire Weakness" feature
//  (flags.nix-module.vampireWeakness) that Nix Fix runs (scripts/vampire-weakness.mjs + scripts/sunlight.mjs):
//   - Sunlight: 20 radiant at the start of its turn in sunlight; disadvantage on attack rolls and ability checks
//     while in sunlight. Sunlight = a sunlight spell's light (Daylight, Dawn, Sunbeam...) or a Region named
//     "Sunlight" / "Daylight" the GM draws (cover the map for a sunny outdoor scene).
//   - Running Water: 20 acid at the end of its turn in a Region named "Running Water".
//   - Stake to the Heart: the Staked button applies Paralyzed (delete the effect when the stake comes out).
//   - Forbiddance: text only.
//  Chris's Premades 1 (1.5.52) has a Medkit "Vampire Weakness" with three buttons and no macro (its Sunlight damage is
//  typed "none"); Chris's Premades 2 (2.1.9) / CAT (0.1.9) have none. An existing "Vampire Weakness" item is updated
//  in place (its description is kept); don't update it from the Medkit afterwards (that replaces these buttons).
// =====================================================================
const MOD = 'nix-module';
const V14 = false;
const actors = Array.from(new Set(canvas.tokens.controlled.map(t => t.actor).filter(Boolean)));
if (!actors.length) return ui.notifications.warn('Vampire Weakness: no Court vampires found (bind them in the Nix Fix window).');
const ACT = {sun: 'nixVampWeakSun00', water: 'nixVampWeakWat00', stake: 'nixVampWeakStk00'};
const STAKED = 'nixVampStaked000';
const special = {type: 'special', value: null, override: false, condition: ''};
const self = {range: {value: '', units: 'self', special: '', override: true},
    target: {affects: {type: 'self', count: '', choice: false, special: ''}, template: {type: '', size: '', units: 'ft', count: '', contiguous: false}, prompt: false, override: true}};
const part = type => ({number: null, denomination: null, bonus: '20', types: [type], custom: {enabled: false, formula: ''}, scaling: {mode: '', number: null, formula: ''}});
const dmgAct = (id, name, type) => ({_id: id, type: 'damage', name, sort: 0, activation: special, ...self,
    consumption: {targets: [], scaling: {allowed: false, max: ''}, spellSlot: false},
    damage: {critical: {allow: false, bonus: ''}, parts: [part(type)]}, effects: [], flags: {[MOD]: {vampireWeakness: true}}});
const TEXT = '<p><b>Forbiddance.</b> It can\'t enter a residence without an invitation from one of the occupants.</p>'
    + '<p><b>Running Water.</b> It takes 20 Acid damage if it ends its turn in running water.</p>'
    + '<p><b>Stake to the Heart.</b> If a weapon that deals Piercing damage is driven into its heart while it is Incapacitated in its resting place, it has the Paralyzed condition until the weapon is removed.</p>'
    + '<p><b>Sunlight.</b> It takes 20 Radiant damage if it starts its turn in sunlight. While in sunlight, it has Disadvantage on attack rolls and ability checks.</p>';
const NOTE = '<p><i>Nix Fix:</i> sunlight damage at the start of its turn and running-water damage at the end of it are automatic in combat '
    + '(sunlight = a sunlight spell, or a Region named "Sunlight" / "Daylight"; running water = a Region named "Running Water"), as are the disadvantages in sunlight. '
    + 'The buttons are for outside combat. Staked: Paralyzed until you delete the effect.</p>';
const report = [];
for (const actor of actors) {
    const it0 = actor.items.find(i => i.flags?.[MOD]?.vampireWeakness) ?? actor.items.find(i => /^vampire weakness/i.test(i.name.trim()));
    const old = String(it0?.system?.description?.value ?? '');
    const desc = (old.replace(/<p><i>Nix Fix:<\/i>[\s\S]*?<\/p>/g, '').trim() || TEXT) + NOTE;
    const data = {
        name: 'Vampire Weakness', type: 'feat', img: it0?.img ?? 'icons/svg/blood.svg',
        system: {type: {value: actor.type === 'npc' ? 'monster' : '', subtype: ''}, description: {value: desc},
            activities: {
                [ACT.sun]: dmgAct(ACT.sun, 'Sunlight (20 Radiant)', 'radiant'),
                [ACT.water]: dmgAct(ACT.water, 'Running Water (20 Acid)', 'acid'),
                [ACT.stake]: {_id: ACT.stake, type: 'utility', name: 'Staked (Paralyzed)', sort: 0, activation: special, ...self,
                    consumption: {targets: [], scaling: {allowed: false, max: ''}, spellSlot: false}, effects: [{_id: STAKED}], roll: {formula: '', name: '', prompt: false, visible: false},
                    flags: {[MOD]: {vampireWeakness: true}}}
            }},
        flags: {[MOD]: {vampireWeakness: {version: 1}}}
    };
    let it;
    if (it0) {
        const {type, ...upd} = data;
        // Medkit buttons from Chris's Premades 1 (Running Water / Sunlight / Staked) go: these replace them.
        const gone = Array.from(it0.system.activities ?? []).filter(a => !Object.values(ACT).includes(a.id)).map(a => a.id);
        for (const id of gone) await actor.items.get(it0.id).deleteActivity(id);
        await actor.items.get(it0.id).update(upd);
        it = actor.items.get(it0.id);
    } else [it] = await actor.createEmbeddedDocuments('Item', [data]);
    const eff = {name: 'Staked', img: 'icons/svg/paralysis.svg', transfer: false, disabled: false, statuses: ['paralyzed'],
        description: '<p>A stake through the heart: Paralyzed until the weapon is removed (delete this effect).</p>', flags: {[MOD]: {vampireStaked: true}}};
    const oldStaked = it.effects.filter(e => e.id !== STAKED && /^staked\b/i.test(e.name ?? '')).map(e => e.id);   // the Medkit's own
    if (oldStaked.length) await it.deleteEmbeddedDocuments('ActiveEffect', oldStaked);
    if (it.effects.get(STAKED)) await it.effects.get(STAKED).update(eff);
    else await it.createEmbeddedDocuments('ActiveEffect', [{_id: STAKED, ...eff}], {keepId: true});
    const ss = actor.items.filter(i => /sunlight sensitivity/i.test(i.name));
    report.push('<b>' + actor.name + '</b>: ' + (it0 ? 'updated' : 'added') + ' Vampire Weakness'
        + (ss.length ? ' (also has ' + ss.map(i => i.name).join(', ') + ': both count, disadvantage once)' : '') + '.');
}
const api = game.modules.get(MOD)?.api;
if (!api?.vampireWeakness) report.push('<b>Nix Fix\'s Vampire Weakness runtime isn\'t running</b>: update Nix Fix and reload.');
await ChatMessage.create({whisper: [game.user.id], content: '<b>Nix Fix: Vampire Weakness' + (V14 ? ' (v14)' : '') + '</b><ul><li>' + report.join('</li><li>') + '</li></ul>'
    + 'In combat: 20 radiant when one starts its turn in sunlight, 20 acid when one ends its turn in running water; disadvantage on attack rolls and ability checks while in sunlight. '
    + 'Sunlight is a sunlight spell (Daylight, Dawn, Sunbeam) or a Region you name "Sunlight" or "Daylight"; running water is a Region you name "Running Water". '
    + 'Staked: the item\'s button (Paralyzed until you delete it). Forbiddance: yours to rule.'});
